#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

cd "$(dirname "$0")/.."
ENV_FILE=".env.development.local"   # loaded ONLY by `next dev` (never baked into production builds); ignored by git

banner "Crownd · Conectar o Stripe"

# Resolve the Stripe CLI even right after a winget install (PATH not refreshed yet).
stripe_bin() {
  if command -v stripe >/dev/null 2>&1; then command -v stripe; return 0; fi
  local links="${LOCALAPPDATA:-$HOME/AppData/Local}/Microsoft/WinGet/Links/stripe.exe"
  [[ -x "$links" ]] && { printf '%s' "$links"; return 0; }
  local pkg; pkg=$(ls "${LOCALAPPDATA:-$HOME/AppData/Local}"/Microsoft/WinGet/Packages/Stripe.StripeCli*/stripe.exe 2>/dev/null | head -n1 || true)
  [[ -n "$pkg" ]] && { printf '%s' "$pkg"; return 0; }
  return 1
}

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Chave secreta de TESTE"
say "Começamos sempre em modo teste: nenhum dinheiro real se move."
open_url "https://dashboard.stripe.com/test/apikeys"
step "Confirme que o seletor 'Test mode' / 'Ambiente de teste' está LIGADO (topo da página)."
step "Na linha 'Secret key', clique em 'Reveal test key' e copie (começa com sk_test_)."
while true; do
  ask_secret STRIPE_SECRET_KEY "Cole a chave secreta de teste (fica oculta):"
  # Windows terminals sometimes paste twice into hidden prompts: collapse an exact duplicate.
  _half=$(( ${#STRIPE_SECRET_KEY} / 2 ))
  if (( ${#STRIPE_SECRET_KEY} % 2 == 0 && _half > 0 )) && [[ "${STRIPE_SECRET_KEY:0:_half}" == "${STRIPE_SECRET_KEY:_half}" ]]; then
    STRIPE_SECRET_KEY="${STRIPE_SECRET_KEY:0:_half}"
    note "A chave foi colada duas vezes; mantive uma cópia."
  fi
  if [[ ! "$STRIPE_SECRET_KEY" =~ ^(sk|rk)_test_ ]]; then
    warn "Esperado sk_test_… — nunca use a chave live aqui. Tente de novo."
    continue
  fi
  if curl -s -u "$STRIPE_SECRET_KEY:" https://api.stripe.com/v1/balance | grep -q '"error"'; then
    warn "O Stripe recusou essa chave. Copie de novo (botão de copiar ao lado da chave) e cole uma única vez."
    continue
  fi
  note "Chave aceita pelo Stripe."
  break
done
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
pause "Enter para validar a chave"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Diagnóstico da conta"
say "Validando a chave, o país da conta e cobrando 1 sessão de teste por moeda (20 edições)…"
npm run --silent stripe:doctor || warn "O diagnóstico apontou itens a resolver; os próximos passos cuidam deles."
pause "Leia o resultado acima e aperte Enter"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Métodos de pagamento locais"
say "O Checkout mostra a cada comprador os métodos do país dele. Ligue os que o diagnóstico marcou com ○."
open_url "https://dashboard.stripe.com/test/settings/payment_methods"
step "Na configuração padrão, ative: Pix, Boleto, iDEAL, Bancontact, BLIK, Przelewy24, Swish, TWINT, Klarna, PayPal,"
step "Konbini, PayPay, Cartes Bancaires, KakaoPay, Naver Pay, OXXO, Afterpay/Clearpay, Apple Pay, Google Pay, Link."
note "Alguns podem não aparecer para a sua conta (depende do país da empresa). Tudo bem: veja docs/04-pagamentos.md."
pause "Enter quando terminar"
if confirm "Rodar o diagnóstico de novo para conferir?"; then
  npm run --silent stripe:doctor || true
  pause "Enter para continuar"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Instalar o Stripe CLI"
say "O CLI encaminha os webhooks do Stripe para o seu localhost."
if STRIPE_BIN=$(stripe_bin); then
  note "Já instalado: $("$STRIPE_BIN" version 2>/dev/null | head -n1)"
else
  if confirm "Instalar agora via winget (pacote oficial Stripe.StripeCli)?"; then
    winget install --id Stripe.StripeCli -e --accept-source-agreements --accept-package-agreements || true
  else
    open_url "https://github.com/stripe/stripe-cli/releases/latest"
    step "Baixe stripe_*_windows_x86_64.zip, extraia o stripe.exe para uma pasta no PATH."
    pause "Enter quando instalar"
  fi
  STRIPE_BIN=$(stripe_bin) || { warn "Stripe CLI não encontrado. Abra um terminal novo e rode: npm run stripe:setup"; SKIPPED+=("Instalar Stripe CLI e rodar o wizard de novo"); finish; return; }
fi
pause "Enter para continuar"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Login do Stripe CLI"
say "Vai abrir o navegador com um código de pareamento. Confira se o código bate e clique em 'Allow access'."
note "Entre na MESMA conta Stripe da chave do passo 1."
"$STRIPE_BIN" login || warn "Login não concluído; rode depois: stripe login"
pause "Enter quando o terminal mostrar 'Done!'"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Segredo do webhook local"
say "Pegando o segredo de assinatura usado pelo 'stripe listen' (automático, sem copiar e colar)…"
if WHSEC=$("$STRIPE_BIN" listen --print-secret 2>/dev/null) && [[ "$WHSEC" == whsec_* ]]; then
  write_env STRIPE_WEBHOOK_SECRET "$WHSEC"
else
  warn "Não consegui obter o segredo automaticamente."
  step "Rode em outro terminal: npm run stripe:listen — ele imprime 'Your webhook signing secret is whsec_…'"
  ask_secret STRIPE_WEBHOOK_SECRET "Cole o whsec_… (fica oculto):"
  write_env STRIPE_WEBHOOK_SECRET "$STRIPE_WEBHOOK_SECRET"
fi
pause "Enter para continuar"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Impostos automáticos (Stripe Tax) — opcional"
say "Calcula IVA/GST por país (UE, UK, AU, JP…). Preços ficam 'imposto incluso': o lance cobrado não muda."
note "Só ligue depois de configurar o endereço da empresa e os registros fiscais no Stripe Tax."
if confirm "Ativar o Stripe Tax agora?"; then
  open_url "https://dashboard.stripe.com/test/settings/tax"
  step "Preencha o endereço da origem (empresa) e o código de produto padrão; adicione registros onde já for registrado."
  pause "Enter quando o Stripe Tax mostrar status ativo"
  if curl -s -u "$STRIPE_SECRET_KEY:" https://api.stripe.com/v1/tax/settings | grep -q '"status": *"active"'; then
    write_env STRIPE_AUTOMATIC_TAX "1"
  else
    warn "O Stripe ainda não mostra o Stripe Tax como ativo, então deixei desligado para o checkout não falhar."
    write_env STRIPE_AUTOMATIC_TAX "0"
    SKIPPED+=("Stripe Tax: conclua a ativação (Settings → Tax) e rode o wizard de novo")
  fi
else
  write_env STRIPE_AUTOMATIC_TAX "0"
  SKIPPED+=("Stripe Tax: ligar antes de vender para consumidores na UE/UK/AU/JP (rode o wizard de novo)")
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Teste ponta a ponta"
NPM="npm"; [[ "$(uname -s)" == MINGW* || "$(uname -s)" == MSYS* ]] && NPM="npm.cmd"
say "Abra DOIS terminais na pasta do projeto (no PowerShell use npm.cmd):"
step "Terminal A:  $NPM run dev   (pule se o site já estiver aberto em localhost:3010)"
step "Terminal B:  $NPM run stripe:listen"
say "Depois:"
step "Abra http://localhost:3010/br, cole um link qualquer, dê um lance e pague com o cartão 4242 4242 4242 4242 (validade futura, CVC 123)."
step "Volte ao board: o produto deve aparecer na posição paga, e o Terminal B mostra '[200] POST /api/webhooks/stripe'."
note "Teste também outra moeda: /jp (JPY, sem centavos) e /nl com iDEAL."
SKIPPED+=("Produção: com a chave LIVE, rode  npm run stripe:webhook -- --url https://crownd.dev  e copie o segredo de .env.production.local para a hospedagem")
pause "Enter para finalizar"

finish
}

run_wizard "$@"; exit
